-- بيانات تجريبية للمعاينة فقط — NAYVO
--
-- الغرض: تعبئة المتجر بمنتجات وبانر سحب حتى تظهر الشاشات بشكلها النهائي
-- قبل إدخال البيانات الحقيقية. هذه ليست بيانات حقيقية ولا يجوز عرضها
-- على أنها كذلك (راجع RELEASE.md).
--
-- التشغيل:
--   docker compose -f docker-compose.prod.yml exec -T db \
--     psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" < scripts/sql/demo-seed.sql
--
-- الحذف (كل ما يضيفه هذا الملف معرّفاته تبدأ بـ demo-):
--   DELETE FROM draws    WHERE id LIKE 'demo-%';
--   DELETE FROM products WHERE id LIKE 'demo-%';
--
-- الصور مضمّنة كـ data: URI بصيغة SVG، فلا تحتاج أي ملفات أو شبكة.

BEGIN;

-- إعادة التشغيل آمنة: نمسح النسخة السابقة من البيانات التجريبية أولاً.
DELETE FROM draws    WHERE id LIKE 'demo-%';
DELETE FROM products WHERE id LIKE 'demo-%';

